update public.counties
set
  highlight_image_url = raw_county_highlight_images.highlight_image_url,
  highlight_image_source = raw_county_highlight_images.highlight_image_source,
  highlight_image_source_url = raw_county_highlight_images.highlight_image_source_url,
  highlight_image_licence = raw_county_highlight_images.highlight_image_licence,
  highlight_image_licence_url = raw_county_highlight_images.highlight_image_licence_url,
  highlight_image_attribution = raw_county_highlight_images.highlight_image_attribution,
  highlight_image_last_verified_at =
    raw_county_highlight_images.highlight_image_last_verified_at::date
from raw_county_highlight_images
where counties.id = raw_county_highlight_images.county_id
  and counties.slug = raw_county_highlight_images.county_slug;
